import{_ as n,y as l,a as i,o as d,a2 as a,g as t,D as s,I as r}from"./chunks/framework.DCcmcJcL.js";const y=JSON.parse('{"title":"Catalog Rules","description":"","frontmatter":{},"headers":[],"relativePath":"marketing/catalog-rules.md","filePath":"marketing/catalog-rules.md","lastUpdated":1789441803000}'),u={name:"marketing/catalog-rules.md"};function g(h,e,c,p,m,f){const o=l("ImagePopup");return d(),i("div",null,[e[5]||(e[5]=a('<h1 id="catalog-rules" tabindex="-1">Catalog Rules <a class="header-anchor" href="#catalog-rules" aria-label="Permalink to &quot;Catalog Rules&quot;">​</a></h1><p>A catalog rule lowers the price of products before they&#39;re added to the cart, so shoppers see the discounted price while they browse. Use it for a sale on a category, or for lower prices for your wholesale customers.</p><p>To give a discount in the cart or with a coupon code, use <a href="./cart-rules.html">cart rules</a> instead.</p><h2 id="create-a-catalog-rule" tabindex="-1">Create a catalog rule <a class="header-anchor" href="#create-a-catalog-rule" aria-label="Permalink to &quot;Create a catalog rule&quot;">​</a></h2>',4)),t("ol",null,[e[1]||(e[1]=t("li",null,[t("p",null,[r("Go to "),t("strong",null,"Marketing >> Promotions >> Catalog Rules"),r(".")])],-1)),e[2]||(e[2]=t("li",null,[t("p",null,[r("Click "),t("strong",null,"Create Catalog Rule"),r(".")])],-1)),t("li",null,[e[0]||(e[0]=t("p",null,"Fill in the sections described below.",-1)),s(o,{src:"/images/marketing/catalog-rule-create.png",alt:"The Create Catalog Rule page with a Categories condition for Mens, a 15 percent discount and the Settings panel"})]),e[3]||(e[3]=t("li",null,[t("p",null,[r("In the "),t("strong",null,"Settings"),r(" panel, switch "),t("strong",null,"Status"),r(" on. A new rule starts switched off.")])],-1)),e[4]||(e[4]=t("li",null,[t("p",null,[r("Click "),t("strong",null,"Save Catalog Rule"),r(".")])],-1))]),e[6]||(e[6]=a('<p>You see &quot;Catalog rule created successfully&quot;.</p><h3 id="general-settings-and-marketing-time" tabindex="-1">General, Settings and Marketing Time <a class="header-anchor" href="#general-settings-and-marketing-time" aria-label="Permalink to &quot;General, Settings and Marketing Time&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>Identifies the rule in the admin panel</td></tr><tr><td><strong>Description</strong></td><td>Your own notes about the rule</td></tr><tr><td><strong>Priority</strong></td><td>The order rules are applied in, starting from the lowest number</td></tr><tr><td><strong>Channels</strong></td><td>The channels the rule works on</td></tr><tr><td><strong>Customer Groups</strong></td><td>The customer groups who see the lower price</td></tr><tr><td><strong>Status</strong></td><td>Switches the rule on or off. Off by default, and a rule that&#39;s off doesn&#39;t apply.</td></tr><tr><td><strong>From</strong> and <strong>To</strong></td><td>Dates, not times. A rule starts at the beginning of the <strong>From</strong> date and ends at the end of the <strong>To</strong> date. Leave them empty for no start or end date.</td></tr></tbody></table><h3 id="conditions" tabindex="-1">Conditions <a class="header-anchor" href="#conditions" aria-label="Permalink to &quot;Conditions&quot;">​</a></h3><p>Conditions decide which products get the lower price. Leave them empty to apply the rule to every product.</p><ol><li>Choose <strong>All Conditions are true</strong> or <strong>Any Conditions are true</strong>.</li><li>Click <strong>Add Condition</strong>.</li><li>Choose the product attribute, the operator and the value.</li></ol><p>You can check <strong>Categories</strong>, <strong>Attribute Family</strong> and your product attributes, listed by name. For <strong>Categories</strong>, tick the categories in the tree. Remove a condition with the bin icon beside it.</p><p>The operators depend on the attribute, as on the <a href="./cart-rules.html#conditions">cart rules</a> page: numbers and dates offer comparisons such as <strong>Equals or greater than</strong>, text offers <strong>Contain</strong> and <strong>Does not contain</strong>, and categories offer <strong>Contains</strong> and <strong>Does not contain</strong>.</p><p>Conditions are checked on each simple product and on each variant of a configurable product. Configurable, bundle and grouped products aren&#39;t checked themselves; their prices follow the products they&#39;re made of.</p><h3 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Action Type</strong></td><td><strong>Percentage of Product Price</strong> takes a percentage off. <strong>Fixed Amount</strong> takes a set amount off.</td></tr><tr><td><strong>Discount Amount</strong></td><td>A percentage from 0 to 100, or an amount. The price never goes below 0.</td></tr><tr><td><strong>End other rules</strong></td><td><strong>Yes</strong> stops rules with a higher <strong>Priority</strong> number from changing the price of the products this rule covers</td></tr></tbody></table><p>When several rules cover the same product, they&#39;re applied in <strong>Priority</strong> order until a rule with <strong>End other rules</strong> set to <strong>Yes</strong>.</p><h2 id="when-prices-change" tabindex="-1">When prices change <a class="header-anchor" href="#when-prices-change" aria-label="Permalink to &quot;When prices change&quot;">​</a></h2><p>The form shows a note that saving a rule updates the price of every product it applies to.</p><ul><li><strong>When you save a rule</strong>, Bagisto recalculates the prices of the products it covers. On many stores this runs in the background, so prices change a little after you save.</li><li><strong>When you delete a rule</strong>, its discount is removed. Where other rules cover the same products, their prices are fully corrected by the nightly update.</li><li><strong>When you save a product</strong>, its catalog rule prices are recalculated.</li><li><strong>Every night at 00:01</strong>, Bagisto recalculates all catalog rule prices, so rules start and stop on their dates.</li></ul><div class="warning custom-block"><p class="custom-block-title">Catalog rules need scheduled tasks</p><p>Catalog rule prices are calculated for a few days at a time, and the nightly update keeps them current. It runs through the scheduled tasks your developer or host sets up for Bagisto. Without them, every catalog rule, dated or not, stops lowering prices within about two days of the last save. See <a href="./../getting-started/scheduled-tasks.html">Scheduled Tasks</a>.</p></div><h2 id="manage-catalog-rules" tabindex="-1">Manage catalog rules <a class="header-anchor" href="#manage-catalog-rules" aria-label="Permalink to &quot;Manage catalog rules&quot;">​</a></h2><p>The <strong>Catalog Rules</strong> list shows each rule&#39;s <strong>ID</strong>, <strong>Name</strong>, <strong>Start</strong>, <strong>End</strong>, <strong>Status</strong> and <strong>Priority</strong>, with icons to edit and delete it.</p>',18)),s(o,{src:"/images/marketing/catalog-rules.png",alt:"The Catalog Rules list with the Weekend Apparel Sale rule"}),e[7]||(e[7]=t("h2",{id:"what-shoppers-see",tabindex:"-1"},[r("What shoppers see "),t("a",{class:"header-anchor",href:"#what-shoppers-see","aria-label":'Permalink to "What shoppers see"'},"​")],-1)),e[8]||(e[8]=t("p",null,[r("Shoppers in the rule's customer groups see the lower price on product listings and product pages, on the rule's channels. They see the lowest of the catalog rule price, the product's special price and its customer group price. "),t("a",{href:"./cart-rules.html"},"Cart rules"),r(" can then discount the cart further.")],-1))])}const C=n(u,[["render",g]]);export{y as __pageData,C as default};
